extends CharacterBody2D

const SPEED := 200.0


func _physics_process(_delta: float) -> void:
	if Input.is_action_pressed("ui_right"):
		velocity = Vector2(SPEED, 0.0)
	else:
		velocity = Vector2.ZERO
	move_and_slide()

extends CharacterBody2D

const GRAVITY := 980.0


func _physics_process(delta: float) -> void:
	if is_on_floor():
		velocity.y = 0.0
	else:
		velocity.y += GRAVITY * delta
	move_and_slide()

extends Label

var score: int = 0


func _ready() -> void:
	score = 0
	_update_text()


func add(points: int) -> void:
	score += points
	_update_text()


func _update_text() -> void:
	text = "Score: %d" % score

extends RefCounted


static func save_data(data: Dictionary, path: String) -> void:
	var file := FileAccess.open(path, FileAccess.WRITE)
	if file == null:
		push_error("Could not open %s for writing: %s" % [path, error_string(FileAccess.get_open_error())])
		return
	file.store_string(JSON.stringify(data, "\t"))
	file.close()


static func load_data(path: String) -> Dictionary:
	if not FileAccess.file_exists(path):
		return {}
	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		push_error("Could not open %s for reading: %s" % [path, error_string(FileAccess.get_open_error())])
		return {}
	var text := file.get_as_text()
	file.close()
	var parsed: Variant = JSON.parse_string(text)
	if parsed is Dictionary:
		return parsed
	push_error("Save file %s does not contain a JSON object" % path)
	return {}

extends Node

enum State { CLOSED, OPENING, OPEN }

const OPEN_DURATION := 0.5

var state: State = State.CLOSED
var _elapsed := 0.0


func interact() -> void:
	if state == State.CLOSED:
		state = State.OPENING
		_elapsed = 0.0


func _process(delta: float) -> void:
	if state == State.OPENING:
		_elapsed += delta
		if _elapsed >= OPEN_DURATION:
			state = State.OPEN


func get_state_name() -> String:
	match state:
		State.CLOSED:
			return "CLOSED"
		State.OPENING:
			return "OPENING"
		_:
			return "OPEN"

extends RefCounted

var _items: Dictionary = {}


func add_item(item_name: String, count: int) -> void:
	if count <= 0:
		return
	_items[item_name] = get_count(item_name) + count


func remove_item(item_name: String, count: int) -> bool:
	if count <= 0:
		return false
	var current := get_count(item_name)
	if current < count:
		return false
	var remaining := current - count
	if remaining == 0:
		_items.erase(item_name)
	else:
		_items[item_name] = remaining
	return true


func get_count(item_name: String) -> int:
	return int(_items.get(item_name, 0))

extends Node


func load_level(path: String) -> Node:
	var scene := load(path) as PackedScene
	if scene == null:
		push_error("Could not load scene: %s" % path)
		return null
	var level := scene.instantiate()
	add_child(level)
	return level

