extends Node2D

## Casts a ray from `from` to `to` (global coordinates) and returns the first
## collision point, or `to` if nothing is hit. Call from _physics_process.
func first_hit(from: Vector2, to: Vector2) -> Vector2:
	var space_state := get_world_2d().direct_space_state
	var query := PhysicsRayQueryParameters2D.create(from, to)
	var result := space_state.intersect_ray(query)
	if result.is_empty():
		return to
	return result["position"]

extends RefCounted

const DIRECTIONS: Array[Vector2i] = [
	Vector2i(0, -1),
	Vector2i(0, 1),
	Vector2i(-1, 0),
	Vector2i(1, 0),
]


## Returns the shortest 4-directional path from `from` to `to` (both included),
## avoiding wall cells. Returns an empty array if no path exists.
func find_path(size: Vector2i, walls: Array[Vector2i], from: Vector2i, to: Vector2i) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	if size.x <= 0 or size.y <= 0:
		return result
	if not _in_bounds(size, from) or not _in_bounds(size, to):
		return result

	var cell_count := size.x * size.y
	var blocked := PackedByteArray()
	blocked.resize(cell_count)
	for wall in walls:
		if _in_bounds(size, wall):
			blocked[wall.y * size.x + wall.x] = 1

	var start_index := from.y * size.x + from.x
	var goal_index := to.y * size.x + to.x
	if blocked[start_index] == 1 or blocked[goal_index] == 1:
		return result

	if start_index == goal_index:
		result.append(from)
		return result

	var came_from := PackedInt32Array()
	came_from.resize(cell_count)
	came_from.fill(-1)
	came_from[start_index] = start_index

	var queue := PackedInt32Array()
	queue.append(start_index)
	var head := 0
	var found := false

	while head < queue.size():
		var current := queue[head]
		head += 1
		var cell := Vector2i(current % size.x, current / size.x)
		for dir in DIRECTIONS:
			var next := cell + dir
			if not _in_bounds(size, next):
				continue
			var next_index := next.y * size.x + next.x
			if blocked[next_index] == 1 or came_from[next_index] != -1:
				continue
			came_from[next_index] = current
			if next_index == goal_index:
				found = true
				break
			queue.append(next_index)
		if found:
			break

	if not found:
		return result

	var index := goal_index
	while index != start_index:
		result.append(Vector2i(index % size.x, index / size.x))
		index = came_from[index]
	result.append(from)
	result.reverse()
	return result


func _in_bounds(size: Vector2i, cell: Vector2i) -> bool:
	return cell.x >= 0 and cell.y >= 0 and cell.x < size.x and cell.y < size.y

