## Resolves once, with whichever outcome arrives first.
class _Race extends RefCounted:
	signal finished(result: bool)
	var done := false

	func resolve(result: bool) -> void:
		if done:
			return
		done = true
		finished.emit(result)


## Waits until `sig` is emitted or `seconds` of game time pass.
## Returns true if the signal came first, false on timeout.
func wait_for(sig: Signal, seconds: float) -> bool:
	var race := _Race.new()
	var on_signal := func() -> void: race.resolve(true)
	sig.connect(on_signal, CONNECT_ONE_SHOT)

	var tree := get_tree() if is_inside_tree() else Engine.get_main_loop() as SceneTree
	var timer := tree.create_timer(maxf(seconds, 0.0))
	timer.timeout.connect(func() -> void: race.resolve(false))

	var result: bool = await race.finished

	if is_instance_valid(sig.get_object()) and sig.is_connected(on_signal):
		sig.disconnect(on_signal)
	return result
